let calls = 0;
function fib(n) {
  calls++;
  if (n <= 1) return n;
  return fib(n - 1) + fib(n - 2);
}
console.log('fib(30) =', fib(30));
console.log('calls =', calls);

tasks.setup:
let buggyCalls = 0;
function fibBuggy(n, memo = []) {
  buggyCalls++;
  if (n <= 1) return n;
  if (memo[n]) return memo[n];          // BUG: a stored 0 looks falsy
  memo[n] = fibBuggy(n - 1, memo) + fibBuggy(n - 2, memo);
  return memo[n];
}
let goodCalls = 0;
function fibGood(n, memo = []) {
  goodCalls++;
  if (n <= 1) return n;
  if (memo[n] !== undefined) return memo[n];   // explicit sentinel test
  memo[n] = fibGood(n - 1, memo) + fibGood(n - 2, memo);
  return memo[n];
}
console.log('buggy fib(25) =', fibBuggy(25), 'calls =', buggyCalls);
console.log('good  fib(25) =', fibGood(25), 'calls =', goodCalls);
